c(15, "§3.1 table (verbatim); §3.1", "data-caveat", "Prioritised unions (verbatim): " + table("## 3.1 The prioritised picture", 0) + " — praise is near-universal (praise_any 84, 97.67%) so what is praised is the finding: the free model (45.35%) and simplicity (46.51%) are named about equally and far more than any feature; problems are rare and concrete (negative_any 7, 8.14%).", "n/a", "mixed", "praise_any 84 / 97.67%; free_model 39; simplicity 40; negative 7", "none", "table", "generalisable", ["12749498855"], "", "")

c(16, "§3.2 table (verbatim); §3.2", "monetization", "The free model (verbatim): " + table("## 3.2 The free model", 0) + " — 'free' is usually one item in a list of reasons ('+ free + great devs who quickly answer to feedback + great overviews + widgets and streaks + nice and detailed statistics + only anonymized data collection'); reviewers thank the developer for keeping it free ('a big thank-you for keeping it free and without ads — that really makes it the best of all the ones I've used'; 'the dev has generously made it free'); price is a comparison class — 'more feature-rich than several paid counterparts'; reviewers position the app against paid trackers, not other free ones.", "free, no ads", "praise", "MODEL_FREE 30; NO_ADS 12; NO_PAYWALL 7; VS_PAID 7", "build-free", "High-priority", "generalisable", ["13726727720", "14267037223", "14499109087", "13546859530", "13822989969", "13469159788", "14070577157"], "", "")

c(17, "§3.3 table (verbatim); §3.3", "insight", "Simplicity and ease (verbatim): " + table("## 3.3 Simplicity and ease", 0) + " — 'simple' and 'complete' are praised together, not traded off: 'A laconic, simple tracker, and yet it has everything you need'; 'more simplistic, but it still has needed features, like reminders'; 'so many functionalities and so easy and clean'; two US reviewers name feature bloat elsewhere as why they chose it ('many of the other apps just have too many features for my liking').", "minimal but complete", "praise", "simplicity 40 / 46.51%; EASE 27; SIMPLE 20", "product-rule", "High-priority", "generalisable", ["13919140000", "13682234945", "13903380759", "14298354068"], "", "")

c(18, "§3.4 table (verbatim); §3.4", "feature", "The grid, statistics and progress views (verbatim): " + table("## 3.4 The grid", 0) + " — 'very visual and motivating'; 'it is very motivating when you see your progress for the year'; a Russian reviewer searched 'a very long time' for a free app 'with unlimited habits and a clear chart'; yet the grid is named less often than simplicity (16 vs 40) — read as part of an uncluttered whole rather than a standalone reason.", "free grid + week/month/year stats", "praise", "visual_progress 16 / 18.60%; VISUAL 10; STATS_VIEWS 9", "build-free", "High-priority", "generalisable", ["13351647905", "14170605260", "14500697857", "13733717410"], "", "")

c(19, "§3.5 table (verbatim); §3.5", "feature", "Widgets — praised, and the site of most defects (verbatim): " + table("## 3.5 Widgets", 0) + " — U:widget_any 10 (11.63%): the only feature on both sides — 8 praise, 2 of the 7 problem reports involve them (the most detailed bug report calls widgets 'a huge plus' while reporting the counter failing; one cannot add more than one widget with different habits); a reviewer asked for widgets five months after the first widget praise — 'a reviewer who could not find widgets and a reviewer who could not configure several are the same discoverability problem from two sides'; widget praise stops in the final era (8 among 56 before 2026-04-19, 0 among 30 after).", "free interactive widgets; one-habit-per-widget config", "mixed", "widget_any 10 / 11.63%; praise 8; defect 1; config 1; undiscovered 1", "build-free", "High-priority", "generalisable", ["13682367544", "14499109087", "13426911405", "12749498855"], "", "")

c(20, "§3.6 table (verbatim); §3.6", "tactic", "The developer relationship (verbatim): " + table("## 3.6 The developer relationship", 0) + " — U:dev_relationship 25 (29.07%), every one 5★: gratitude PRAISE_DEV_THANKS 23 ('we need more developers like this'; 'the poor guy works on it alone ❤️'), responsiveness DEV_RESPONSIVE 4 ('send him a bug report, expect to hear back in <24 hours'; 'I suggested adding a watch app; I talked to the developer, he replied quickly and said he would try'); no review reports being ignored; gratitude concentrated in Russian reviews (17 of 37 vs 6 of 49).", "solo dev, fast replies, free app", "praise", "dev_relationship 25 / 29.07% / 5.00★; THANKS 23; RESPONSIVE 4", "do", "High-priority", "generalisable", ["14481206696", "14005146777", "13546859530", "13726727720", "14066478851"], "", "")

c(21, "§3.7 table (verbatim); §3.7", "positioning", "Switching and acquisition (verbatim): " + table("## 3.7 Switching and acquisition", 0) + " — U:switching 28 (32.56%): ACQ_TRIED_MANY 16 ('I searched the App Store high and low'), OUT_FOUND_IT 15 ('Finally found what I was looking for'; 'Now I use only this app'), replaced Apple Reminders or a calendar and notes (2; one waters plants with it — USE_NON_HABIT), found through GPT (1 — the only channel named), competitors HabitKit and an unnamed near-identical paid app; apart from one App Store search and one AI recommendation, no review says how it found the app — acquisition channels are almost entirely unrecorded.", "n/a", "praise", "switching 28 / 32.56%; TRIED_MANY 16; FOUND_IT 15; REPLACED_TOOL 2; AI_RECOMMEND 1; COMP_REFERENCE 2", "none", "High-priority", "generalisable", ["14170605260", "13682234945", "13669343653", "14196935443", "14434590887", "12889550610", "13919140000", "14227392787", "13546859530"], "", "an LLM recommendation is the only named acquisition channel")

c(22, "§3.8 table (verbatim); §3.8", "insight", "Outcomes (verbatim): " + table("## 3.8 Outcomes", 0) + " — U:outcome_any 6 (6.98%), none measured: 'the first habit tracker that's actually helped me stay on track without stress. Since using it, my days feel more organized and purposeful'; 'It's helping me and improving my life'; 'outcome evidence is thin, consistent with a tool whose reviewers judge it as a tool rather than as a programme' — 15 report their search ended, six that their life changed.", "n/a", "praise", "outcome_any 6 / 6.98%; FOUND_IT 15", "none", "High-priority", "generalisable", ["12749498855", "14298354068", "13633715337", "14337037720"], "", "")

c(23, "§3.9 table (verbatim); §3.9", "must-never-break", "Defects and friction by type (verbatim): " + table("## 3.9 Defects and friction", 0) + " — date logic 2 (a weekend tick toggles both days; a widget increment lands on the next day — both week/day-boundary errors; 1.0.19 'Custom week start' touches week boundaries, fix not established); launch 1 (12 days after release, 'stopped opening' after 7 days, never repeated); display 1 (transparent icon appearance); statistics basis 1 (yearly % from the habit's start — arguably a design choice); data safety 1 warning + 1 account request while import/export exists per the listing and neither mentions it.", "date-boundary bugs; export undiscovered", "complaint", "defect_any 5 / 5.81%; DATE_LOGIC 2; WONT_OPEN 1; ICON 1; STATS_CALC 1; DATA_LOSS risk 1", "must-never-break", "High-priority", "generalisable", ["13318616929", "13682367544", "12782107949", "13761082816", "13985196266", "13852112119", "13868640698"], "", "")

c(24, "§3.10 table (verbatim); §3.10 request table (verbatim); §3.10", "feature", "Requests (verbatim): " + table("## 3.10 Requests", 0) + " || every request (verbatim): " + table("## 3.10 Requests", 1) + " — frequency is the only request that recurs: five variants of 'a goal that is not every day', one attaching rating elasticity ('if it appears, this app will have no equal'); four of the five on the Russian storefront.", "daily-only goals until 1.0.15", "complaint", "request_any 11 / 12.79%; REQ_FREQUENCY 5; WATCH 2; ACCOUNT 1; SOCIAL 1; PRINT 1; CALENDAR 1", "must-have", "High-priority", "generalisable", ["13766824285", "14005146777", "14196935443", "13868640698", "14074933658", "14048929482"], "", "")

